import { motion } from 'motion/react';
import { useId, useRef, type KeyboardEvent, type ReactNode } from 'react';
import { cn } from '../../lib/cn.ts';
import { DiscreteTabButton } from '../../vendor/uselayouts/discrete-tabs.tsx';

export interface SegmentedTab {
  id: string;
  label: string;
  icon?: ReactNode;
}

export interface SegmentedTabsProps {
  tabs: SegmentedTab[];
  value: string;
  onChange: (id: string) => void;
  /** `segmented`: sliding indicator. `discrete`: uselayouts pills that widen to show the label. */
  variant?: 'segmented' | 'discrete';
  label?: string;
  className?: string;
}

export function SegmentedTabs({ tabs, value, onChange, variant = 'segmented', label = 'Tabs', className }: SegmentedTabsProps) {
  const scope = useId();
  const listRef = useRef<HTMLDivElement>(null);

  const onKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
    const i = tabs.findIndex((t) => t.id === value);
    let next = -1;
    if (e.key === 'ArrowRight') next = (i + 1) % tabs.length;
    else if (e.key === 'ArrowLeft') next = (i - 1 + tabs.length) % tabs.length;
    else if (e.key === 'Home') next = 0;
    else if (e.key === 'End') next = tabs.length - 1;
    if (next < 0) return;
    e.preventDefault();
    const t = tabs[next];
    if (!t) return;
    onChange(t.id);
    requestAnimationFrame(() => listRef.current?.querySelector<HTMLElement>(`[id="${scope}-tab-${t.id}"]`)?.focus());
  };

  return (
    <div
      ref={listRef}
      data-fx-component="segmented-tabs"
      data-variant={variant}
      role="tablist"
      aria-label={label}
      onKeyDown={onKeyDown}
      className={cn(
        variant === 'segmented'
          ? 'relative inline-flex gap-0.5 rounded-full bg-muted p-1'
          : 'inline-flex items-center gap-3',
        className,
      )}
    >
      {tabs.map((t) =>
        variant === 'discrete' ? (
          <DiscreteTabButton
            key={t.id}
            id={t.id}
            scope={scope}
            title={t.label}
            icon={t.icon}
            isActive={t.id === value}
            onSelect={() => onChange(t.id)}
          />
        ) : (
          <button
            key={t.id}
            type="button"
            role="tab"
            id={`${scope}-tab-${t.id}`}
            aria-selected={t.id === value}
            tabIndex={t.id === value ? 0 : -1}
            onClick={() => onChange(t.id)}
            className={cn(
              'relative inline-flex h-8 cursor-pointer items-center gap-1.5 rounded-full px-3.5 text-sm font-medium transition-colors focus-visible:outline-2 focus-visible:outline-ring',
              t.id === value ? 'text-foreground' : 'text-muted-foreground hover:text-foreground',
            )}
          >
            {t.id === value ? (
              <motion.span
                layoutId={`${scope}-indicator`}
                aria-hidden="true"
                className="absolute inset-0 rounded-full bg-background shadow-sm"
                transition={{ type: 'spring', damping: 30, stiffness: 420, mass: 0.8 }}
              />
            ) : null}
            {t.icon ? <span className="relative z-10 flex">{t.icon}</span> : null}
            <span className="relative z-10">{t.label}</span>
          </button>
        ),
      )}
    </div>
  );
}

/**
 * Vendored from iurvish/uselayouts
 * Path: registry/default/example/discrete-tabs.tsx
 * Commit: 07cc4f4fb8e0
 * Licence: MIT (see packages/fx/ATTRIBUTION.md)
 * Adapted: the demo's hard-coded tab list and inline SVG icons are replaced by
 * a props-driven DiscreteTabButton (icon is a ReactNode); layout ids are scoped
 * per instance; real tab semantics (role=tab, aria-selected); cn import.
 */
import { AnimatePresence, motion } from 'motion/react';
import type { ReactNode } from 'react';
import { cn } from '../../lib/cn.ts';

const spring = { type: 'spring', damping: 20, stiffness: 230, mass: 1.2 } as const;

export interface DiscreteTabButtonProps {
  id: string;
  title: string;
  icon?: ReactNode;
  isActive: boolean;
  onSelect: () => void;
  scope: string;
  panelId?: string;
}

/** The pill from uselayouts' discrete tabs: it widens to reveal its label when active. */
export function DiscreteTabButton({ id, title, icon, isActive, onSelect, scope, panelId }: DiscreteTabButtonProps) {
  return (
    <motion.button
      type="button"
      role="tab"
      id={`${scope}-tab-${id}`}
      aria-selected={isActive}
      aria-controls={panelId}
      tabIndex={isActive ? 0 : -1}
      layout
      transition={{ layout: spring }}
      onClick={onSelect}
      className={cn(
        'flex h-fit w-fit cursor-pointer items-center gap-1.5 overflow-hidden rounded-[25px] bg-secondary p-3 font-mono text-sm font-medium uppercase outline outline-2 outline-border transition-colors duration-75 ease-out focus-visible:outline-ring',
        isActive ? 'px-4 text-primary' : 'px-3 text-muted-foreground',
      )}
    >
      {icon ? <span className="flex shrink-0 items-center [&>svg]:size-[18px]">{icon}</span> : null}
      <AnimatePresence initial={false}>
        {isActive || !icon ? (
          <motion.span
            key="label"
            initial={{ opacity: 0, filter: 'blur(4px)' }}
            animate={{ opacity: 1, filter: 'blur(0px)' }}
            exit={{ opacity: 0, filter: 'blur(4px)' }}
            transition={{ duration: 0.2, ease: [0.86, 0, 0.07, 1] }}
            className="relative inline-block whitespace-nowrap"
          >
            {title}
          </motion.span>
        ) : null}
      </AnimatePresence>
    </motion.button>
  );
}
